css:
.signup {
  max-inline-size: 28rem;
  margin-inline: auto;
  padding-block: var(--va-space-8, 2rem);
  padding-inline: var(--va-space-4, 1rem);
}

.signup h1 {
  margin-block: 0 var(--va-space-2, 0.5rem);
}

.signup-intro {
  margin-block: 0 var(--va-space-6, 1.5rem);
}

.signup-form {
  display: flex;
  flex-direction: column;
  gap: var(--va-space-5, 1.25rem);
}

.signup-actions {
  margin-block-start: var(--va-space-2, 0.5rem);
}
